    /**
     * Add a proof of the kind (receipt or photo; null: none chosen, a receipt) to a claim, raising its proofs count by
     * one. Refused for a SETTLED, VOID or DELETED claim, or a closed period.
     */
    @Transactional
    public Claim addProof(String sheetId, String user, Long id, String kind) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                || claim.getStatus() == ClaimStatus.DELETED) {
            throw new ClaimProofException(id, "it is " + claim.getStatus() + ", a proof cannot be added");
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        claim.addProof(kind == null ? Sheet.PROOF_KINDS.get(0) : kind);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", user, person, saved) + numberOf(saved.getNumber())
                + " proofs=" + saved.getProofs() + (kind == null ? "" : " kind=" + kind));
        return saved;
    }

    /**
     * Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date becomes the sheet's today.
     * Refused for any other status, and for a claim already reminded on the sheet's today. While the sheet has an
     * escalation gap, a claim never escalated whose previous reminder was at least that many days before the sheet's
     * today is escalated: ESCALATE is written after the REMIND line.
     */
    @Transactional
    public Claim remind(String sheetId, String user, Long id) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimRemindException(id, "it is " + claim.getStatus()
                    + ", only an OPEN or PENDING claim can be reminded");
        }
        LocalDate today = sheets.today(sheetId);
        if (today.equals(claim.getRemindedOn())) {
            throw new ClaimRemindException(id, "it was already reminded on " + today);
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        Integer gap = sheets.escalateAfter(sheetId);
        boolean escalate = gap != null && !claim.isEscalated() && claim.getRemindedOn() != null
                && !claim.getRemindedOn().plusDays(gap).isAfter(today);
        claim.setRemindedOn(today);
        if (escalate) {
            claim.setEscalated(true);
        }
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("REMIND", user, person, saved) + numberOf(saved.getNumber()));
        if (escalate) {
            audit.recordOnCommit(record("ESCALATE", user, person, saved) + numberOf(saved.getNumber()));
        }
        return saved;
    }

    /**
     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date (its person's
     * grade's own then, else the sheet's) cannot be settled or approved while it has no proof; refused then. A due of
     * n/a is within any threshold. While the sheet has proof kinds, such a claim also needs a proof of each kind listed.
     */
    private void requireProof(String sheetId, Person person, Claim claim) {
        Sheet sheet = settings.get(sheetId);
        BigDecimal threshold = sheet.proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
        List<String> missing = sheet.proofKindsNeeded().stream().filter(k -> claim.proofsOf(k) == 0).toList();
        if (threshold == null || (claim.getProofs() > 0 && missing.isEmpty())) {
            return;
        }
        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
        if (due != null && due.compareTo(threshold) > 0) {
            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
                    + " is above the proof threshold " + threshold.toPlainString()
                    + (claim.getProofs() == 0 ? " and it has no proof"
                            : " and it has no proof of kind " + String.join(", ", missing)));
        }
    }

    /** While its person's flag is in force on the sheet's today, only a steward may open a claim of theirs. */
    private void requireUnflagged(String sheetId, String user, Person person, Claim claim) {
        if (person.flagOn(sheets.today(sheetId)) != null && roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimActionForbiddenException(claim.getId(), user, "open",
                    person.getName() + " is flagged: only a steward may open their claims");
        }
    }

    /**
     * A claim whose due is above the note threshold in force on its date cannot be opened while its note is empty;
     * refused then. A due of n/a is within any threshold.
     */
    /**
     * Refuse opening a claim when the period its due-by falls in caps each person's claims and its person already has
     * that many OPEN or PENDING claims due by a date in it. The sheet is locked by the caller, so two opens at once are
     * counted against each other.
     */
    private void requireUnderCap(String sheetId, Claim claim) {
        requireUnderMaxOpen(sheetId, claim);
        Period period = periods.on(sheetId, claim.getDueBy()).orElse(null);
        if (period == null || period.getCap() == null) {
            return;
        }
        long held = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, claim.getPersonId()).stream()
                .filter(c -> !c.getId().equals(claim.getId()))
                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                .filter(c -> c.getDueBy() != null && period.contains(c.getDueBy()))
                .count();
        if (held >= period.getCap()) {
            throw new ClaimCapException(claim.getId(), period.getName(), period.getCap());
        }
    }

    /**
     * Refuse opening a claim when the sheet sets a maximum of open claims per person and its person already has that
     * many OPEN or PENDING claims. The sheet is locked by the caller, so two opens at once are counted against each other.
     */
    private void requireUnderMaxOpen(String sheetId, Claim claim) {
        Integer max = settings.get(sheetId).getMaxOpen();
        if (max == null) {
            return;
        }
        long held = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, claim.getPersonId()).stream()
                .filter(c -> !c.getId().equals(claim.getId()))
                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                .count();
        if (held >= max) {
            throw new ClaimMaxOpenException(claim.getId(), max);
        }
    }

    /** Whether the claim's due is above the review threshold in force on its date; a due of n/a is within any. */
    private boolean needsReview(String sheetId, Person person, Claim claim) {
        BigDecimal threshold = settings.get(sheetId).reviewThresholdOn(claim.getDate());
        if (threshold == null) {
            return false;
        }
        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
        return due != null && due.compareTo(threshold) > 0;
    }

    private void requireNote(String sheetId, Person person, Claim claim) {
        BigDecimal threshold = settings.get(sheetId).noteThresholdOn(claim.getDate());
        if (threshold == null || !noteOf(claim.getNote()).isEmpty()) {
            return;
        }
        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
        if (due != null && due.compareTo(threshold) > 0) {
            throw new ClaimNoteException(claim.getId(), "its due " + due.toPlainString()
                    + " is above the note threshold " + threshold.toPlainString() + " and its note is empty");
        }
    }

    /**
     * Only a steward voids a SETTLED claim, and only within the days allowed after its settlement (the date of the last
     * SETTLED line of its status log) by the sheet's today; refused otherwise.
     */
    private void requireSettledVoidable(String sheetId, String user, Claim claim) {
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimActionForbiddenException(claim.getId(), user, "void a settled claim");
        }
        LocalDate settledOn = logOf(claim).stream()
                .filter(l -> l.getStatus() == ClaimStatus.SETTLED)
                .map(ClaimLog::getDate)
                .reduce((first, last) -> last)
                .orElse(null);
        LocalDate today = sheets.today(sheetId);
        if (settledOn == null || today.isAfter(settledOn.plusDays(SETTLED_VOID_DAYS))) {
            throw new ClaimVoidException(claim.getId(), "a settled claim can only be voided within "
                    + SETTLED_VOID_DAYS + " days of its settlement on " + settledOn);
        }
    }

    /** Whether the user is the approver named on the claim's person. */
    private boolean isApproverOf(String sheetId, String user, Claim claim) {
        return people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .map(p -> user.equals(p.getApprover())).orElse(false);
    }

    /** The PENDING claim a steward or the person's approver decides; refused for any other status, a closed period, or any other user. */
    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusException(id, claim.getStatus(), to);
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        if (roles.roleOf(sheetId, user) != Role.STEWARD && !isApproverOf(sheetId, user, claim)) {
            throw new ClaimApprovalForbiddenException(id, user,
                    "only a steward or the person's approver approves or rejects a pending claim");
        }
        return claim;
    }

    /**
     * Fixes the due the claim shows as it settles: the due its statement binds it to (late charge included), else its
     * figure worked out from the rate on the claim's date raised to the floor on its date, with its late charge, frozen
     * in (a correction freezes its bare figure); with no figure it stays live. Gives the due at the
     * end of its audit record.
     */
    private String settle(String sheetId, Person person, Claim claim) {
        BigDecimal figure = figureOf(sheetId, person, claim);
        Sheet sheet = settings.get(sheetId);
        BigDecimal settledDue = figure == null || claim.isBound() || claim.isCorrection() ? figure
                : sheet.liveDue(figure, !claim.isWaived(), overdueBy(sheet, person, claim), claim.getDate());
        claim.setSettledDue(settledDue);
        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
    }

    /** Freeze the claim's due at the one it had as of a date; the CLAIM_SETTLED record names the date at its end. */
    private static String settleAt(Claim claim, DueThen asOf) {
        claim.setSettledDue(asOf.due());
        return " due=" + (asOf.due() == null ? "n/a" : asOf.due().toPlainString()) + " on=" + asOf.on();
    }

    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
    private void log(String sheetId, String user, Person person, Claim claim) {
        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
                shownDue(sheetId, person, claim)));
    }

    /**
     * The claim's due as shown: the one fixed when it was settled, else its live due; two decimals, or n/a.
     */
    private String shownDue(String sheetId, Person person, Claim claim) {
        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
                : liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }

    /**
     * The figure under the claim's due: the due (late charge included) its statement binds it to now, else worked out
     * from the rate.
     */
    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
    }

    /**
     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
     * names none. A correction may not exceed what remains of its target: the target's amount less the amounts of the
     * other corrections against it that are not VOID or DELETED (the claim with the id, the one being changed, left
     * out). Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null for any
     * other claim.
     */
    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects, Long id) {
        if (amount.signum() >= 0) {
            if (corrects != null) {
                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
            }
            return null;
        }
        if (corrects == null) {
            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
        }
        Claim target = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
                .orElseThrow(() -> new ClaimCorrectionException(
                        "Claim " + corrects + " is not a settled claim of the same person"));
        // Locking the target means two corrections of it do not both pass the check.
        claims.findForUpdate(target.getId(), sheetId);
        BigDecimal remaining = target.getAmount();
        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)) {
            if (corrects.equals(other.getCorrects()) && !other.getId().equals(id)
                    && other.getStatus() != ClaimStatus.VOID && other.getStatus() != ClaimStatus.DELETED) {
                remaining = remaining.add(other.getAmount());
            }
        }
        if (amount.negate().compareTo(remaining) > 0) {
            throw new ClaimCorrectionException("A correction of " + amount.negate().toPlainString()
                    + " exceeds the " + remaining.max(BigDecimal.ZERO).toPlainString() + " that remains of claim "
                    + corrects);
        }
        return target.getDate();
    }

    /**
     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
     * date has the claim round (the rate figure, with no floor); null (n/a) with no rate.
     */
    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
        Sheet sheet = settings.get(sheetId);
        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), claim.rateStamp())
                .map(Rate::getPct)
                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getDate(), claim.getRoundingDate()))
                .orElse(null);
    }

    /**
     * The live due on a figure: the greater of the floor in force on the claim's date and the figure, with the late
     * charge on that of an OPEN or PENDING claim overdue on the sheet's today added on top (no late charge on a claim deferred
     * on the sheet's today; a correction has neither floor nor late charge, and a bound claim's figure is its due as
     * shown when bound, late charge included); null (n/a) stays null.
     */
    private BigDecimal liveDue(String sheetId, Person person, Claim claim, BigDecimal figure) {
        Sheet sheet = settings.get(sheetId);
        if (claim.isBound() || claim.isCorrection()) {
            return figure;
        }
        return sheet.liveDue(figure, claim.getStatus().isOpen()
                && !claim.isWaived() && !claim.isDeferredOn(sheet.getToday()), overdueBy(sheet, person, claim), claim.getDate());
    }

    /** The day the claim goes overdue after: its due-by plus the grace days its person's grade has on its date. */
    private static LocalDate overdueBy(Sheet sheet, Person person, Claim claim) {
        return sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
    }

    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
    private static String record(String event, String user, Person person, Claim claim) {
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + " date=" + claim.getDate();
    }

    /** The claim's number at the end of an audit record, or nothing when it has none. */
    private static String numberOf(String number) {
        return number == null ? "" : " number=" + number;
    }

    /**
     * The number a claim due by the date gets when settled or approved: while the sheet numbers by period, the next in its
     * period's own sequence (X for no period); otherwise the next sheet-wide number in the fiscal
     * year of the date (<FY>-<n>).
     */
    public String nextNumber(String sheetId, LocalDate date) {
        if (settings.get(sheetId).numbersByPeriod()) {
            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
        }
        return sheets.nextClaimNumber(sheetId, date);
    }

    /**
     * The terms of the person on the day (the sheet's today a claim is created): their own in force then, else those of
     * the grade they had that day, else the sheet's then.
     */
    private int termsFor(String sheetId, Person person, LocalDate date) {
        Integer own = person.termsOn(date);
        return own != null ? own : settings.termsFor(sheetId, person.gradeOn(date), date);
    }

    private LocalDate dateOr(String sheetId, LocalDate date) {
        return date != null ? date : sheets.today(sheetId);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }

    /** The reference with surrounding spaces removed; null for a blank one (no reference). */
    /**
     * The tags of comma separated text, each trimmed and lower-cased, without repeats, sorted and joined by commas
     * (null when there are none), each noted as used on the sheet.
     */
    private String tagged(String sheetId, String text) {
        if (text == null) {
            return null;
        }
        List<String> list = SheetTag.parse(text);
        for (String tag : list) {
            if (!tags.existsBySheetIdAndTag(sheetId, tag)) {
                tags.save(new SheetTag(sheetId, tag));
            }
        }
        return list.isEmpty() ? null : String.join(",", list);
    }

    private static String refOf(String ref) {
        return ref == null || ref.isBlank() ? null : ref.trim();
    }
}

