102	            if (limit != null && due != null && due.compareTo(limit) > 0) {
103	                status = ClaimStatus.PENDING;
104	            }
105	        }
106	        RollupService.Snapshot before = rollup.snapshot(sheetId);
107	        String due = status == ClaimStatus.SETTLED && asOf != null ? settleAt(claim, asOf)
108	                : status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
109	                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
110	        claim.setStatus(status);
111	        if (status == ClaimStatus.VOID) {
112	            claim.setVoidReason(reason);
113	        }
114	        // Settled one at a time, a claim carries no batch; settled by a bulk settle, it carries that batch's number.
115	        if (status == ClaimStatus.SETTLED || status == ClaimStatus.PENDING) {
116	            claim.setSettleBatch(batch == null ? null : batch.getAsLong());
117	        }
118	        // A claim takes its number when it is settled (a claim numbered before keeps its own); a voided claim keeps
119	        // its number (never reused), and the CLAIM_VOIDED record carries it.
120	        String number = claim.getNumber();
121	        if (status == ClaimStatus.SETTLED && number == null) {
122	            number = nextNumber(sheetId, claim.getDueBy());
123	            claim.setNumber(number);
124	        }
125	        if (status == ClaimStatus.OPEN) {
126	            claim.setOpenedBy(user);
127	        }
128	        // Sent to REVIEW, it records who opened it and its review day; like an OPEN claim it has no number yet.
129	        if (status == ClaimStatus.REVIEW) {
130	            claim.setOpenedBy(user);
131	            claim.setReviewOn(sheets.today(sheetId));
132	        }
133	        // Sent to PENDING, it records its pending day, the latest time it went there.
134	        if (status == ClaimStatus.PENDING) {
135	            claim.setPendingOn(sheets.today(sheetId));
136	        }
137	        Claim saved = claims.saveAndFlush(claim);
138	        log(sheetId, user, person, saved);
139	        String event = switch (status) {
140	            case OPEN -> "CLAIM_OPENED";
141	            case REVIEW -> "CLAIM_REVIEW";
142	            case PENDING -> "CLAIM_PENDING";
143	            case SETTLED -> "CLAIM_SETTLED";
144	            case VOID -> "CLAIM_VOIDED";
145	            case DRAFT, DELETED -> throw new IllegalStateException();
146	        };
147	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due
148	                + (reason == null ? "" : " reason=" + reason));
149	        if (status == ClaimStatus.SETTLED) {
150	            watches.notifyWatchers(sheetId, user, person, number);
151	        }
152	        rollup.recordChanges(sheetId, user, before);
153	        return saved;
154	    }
