166	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.DELETED);
167	        }
168	        if (claim.isLockedAgainst(user)) {
169	            throw new ClaimLockedException(id, claim.getLockedBy());
170	        }
171	        periods.requireOpen(sheetId, claim.getDueBy());
172	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
173	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
174	        RollupService.Snapshot before = rollup.snapshot(sheetId);
175	        claim.setStatus(ClaimStatus.DELETED);
176	        claim.setLockedBy(null);
177	        Claim saved = claims.saveAndFlush(claim);
178	        log(sheetId, user, person, saved);
179	        audit.recordOnCommit(record("CLAIM_DELETED", user, person, saved));
180	        rollup.recordChanges(sheetId, user, before);
181	        return saved;
