184	    /**
185	     * Restore a DELETED claim to DRAFT, only on the sheet's today it was deleted (the date of the last DELETED line of
186	     * its status log). Refused for any other status, a later day, or a claim due by a date in a closed period.
187	     */
188	    @Transactional
189	    public Claim restore(String sheetId, String user, Long id) {
190	        Claim claim = claims.findForUpdate(id, sheetId)
191	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
192	        if (claim.getStatus() != ClaimStatus.DELETED) {
193	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.DRAFT);
194	        }
195	        LocalDate deletedOn = logOf(claim).stream()
196	                .filter(l -> l.getStatus() == ClaimStatus.DELETED)
197	                .map(ClaimLog::getDate)
198	                .reduce((first, last) -> last)
199	                .orElse(null);
200	        LocalDate today = sheets.today(sheetId);
201	        if (!today.equals(deletedOn)) {
202	            throw new ClaimRestoreException(id, "a deleted claim can only be restored on the day it was deleted, "
203	                    + deletedOn);
204	        }
205	        periods.requireOpen(sheetId, claim.getDueBy());
206	        // A restored correction counts against its target again.
207	        if (claim.getCorrects() != null) {
208	            requireCorrection(sheetId, claim.getPersonId(), claim.getAmount(), claim.getCorrects(), id);
209	        }
210	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
211	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
212	        RollupService.Snapshot before = rollup.snapshot(sheetId);
213	        claim.setStatus(ClaimStatus.DRAFT);
214	        Claim saved = claims.saveAndFlush(claim);
215	        log(sheetId, user, person, saved);
216	        audit.recordOnCommit(record("CLAIM_RESTORED", user, person, saved));
217	        rollup.recordChanges(sheetId, user, before);
218	        return saved;
219	    }
