221	    /**
222	     * The reason a claim is voided with: none while the sheet's list of void reasons is empty, else the one given,
223	     * which must be on the list.
224	     */
225	    private String requireVoidReason(String sheetId, Long id, String given) {
226	        List<String> listed = voidReasons.list(sheetId).stream().map(VoidReason::getReason).toList();
227	        if (listed.isEmpty()) {
228	            return null;
229	        }
230	        String reason = given == null ? "" : given.trim();
231	        if (reason.isEmpty()) {
232	            throw new ClaimVoidReasonException(id, "choose a reason from the sheet's void reasons");
233	        }
234	        if (!listed.contains(reason)) {
235	            throw new ClaimVoidReasonException(id, reason + " is not one of the sheet's void reasons");
236	        }
237	        return reason;
238	    }
