240	    /**
241	     * A steward other than its opener or last editor approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
242	     * its figure (the one its statement bound it to, else its live one).
243	     */
244	    @Transactional
245	    public Claim approve(String sheetId, String user, Long id) {
246	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
247	        if (user.equals(claim.getOpenedBy())) {
248	            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
249	        }
250	        if (user.equals(claim.getEditedBy())) {
251	            throw new ClaimApprovalForbiddenException(id, user, "whoever last edited a claim cannot approve it");
252	        }
253	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
254	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
255	        requireProof(sheetId, person, claim);
256	        RollupService.Snapshot before = rollup.snapshot(sheetId);
257	        String due = settle(sheetId, person, claim);
258	        claim.setStatus(ClaimStatus.SETTLED);
259	        // Approved, it takes its number now unless it was numbered before.
260	        if (claim.getNumber() == null) {
261	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
262	        }
263	        Claim saved = claims.saveAndFlush(claim);
264	        log(sheetId, user, person, saved);
265	        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
266	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
267	        rollup.recordChanges(sheetId, user, before);
268	        return saved;
269	    }
