343	    /**
344	     * A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its date and,
345	     * if it was numbered before settlement, takes the next number in the sequence it is numbered in (its old one is never used again), loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
346	     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
347	     * retired before its date, or a user whose role may not reassign.
348	     */
349	    @Transactional
350	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
351	        return reassign(sheetId, user, id, toPersonId, false);
352	    }
