354	    /**
355	     * Reassign as {@link #reassign(String, String, Long, Long)}; with {@code toOwnAllowed} (a bulk reassign) a claim
356	     * already the person's is moved too, listed again as its newest claim.
357	     */
358	    @Transactional
359	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean toOwnAllowed) {
360	        Claim claim = claims.findForUpdate(id, sheetId)
361	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
362	        if (!roles.may(sheetId, user, "reassign")) {
363	            throw new ClaimReassignForbiddenException(id, user);
364	        }
365	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
366	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
367	        }
368	        if (!toOwnAllowed && claim.getPersonId().equals(toPersonId)) {
369	            throw new ClaimReassignException(id, "it is already that person's");
370	        }
371	        periods.requireOpen(sheetId, claim.getDueBy());
372	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
373	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
374	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
375	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
376	        to.requireClaimable(claim.getDate());
377	        RollupService.Snapshot before = rollup.snapshot(sheetId);
378	        claim.setPersonId(to.getId());
379	        claim.setStated(false, null);
380	        claim.setListed(sheets.nextListed(sheetId));
381	        if (claim.getNumber() != null) {
382	            // A moved claim takes the next number in its sequence; its old one is never used again.
383	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
384	        }
385	        Claim saved = claims.saveAndFlush(claim);
386	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
387	                + " from=" + from.getName() + " to=" + to.getName());
388	        rollup.recordChanges(sheetId, user, before);
389	        return saved;
390	    }
