443	    /**
444	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
445	     * bound by no statement (today's rates and grades raised to the floor, with its late charge on that as of today). Refused for any other
446	     * status, a closed period, or a user not a steward.
447	     */
448	    @Transactional
449	    public Claim resettle(String sheetId, String user, Long id) {
450	        Claim claim = claims.findForUpdate(id, sheetId)
451	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
452	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
453	            throw new ClaimResettleForbiddenException(id, user);
454	        }
455	        if (claim.getStatus() != ClaimStatus.SETTLED) {
456	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
457	        }
458	        periods.requireOpen(sheetId, claim.getDueBy());
459	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
460	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
461	        RollupService.Snapshot before = rollup.snapshot(sheetId);
462	        String old = shownDue(sheetId, person, claim);
463	        BigDecimal figure = dueOf(sheetId, person, claim);
464	        Sheet sheet = settings.get(sheetId);
465	        claim.setSettledDue(claim.isCorrection() ? figure
466	                : sheet.liveDue(figure, !claim.isWaived(), overdueBy(sheet, person, claim), claim.getDate()));
467	        Claim saved = claims.saveAndFlush(claim);
468	        log(sheetId, user, person, saved);
469	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
470	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
471	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
472	        rollup.recordChanges(sheetId, user, before);
473	        return saved;
474	    }
