514	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
515	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
516	            throw new ClaimRedateForbiddenException(id, user);
517	        }
518	        if (!claim.getStatus().isOpen()) {
519	            throw new ClaimRedateException(id, "it is " + claim.getStatus()
520	                    + ", only an OPEN or PENDING claim can be re-dated");
521	        }
522	        LocalDate old = claim.getDate();
523	        // Its due-by, and so its period, stays as fixed.
524	        periods.requireOpen(sheetId, claim.getDueBy());
525	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
526	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
