530	        if (!claim.isCorrection()) {
531	            claim.setRoundingDate(date);
532	        }
533	        Claim saved = claims.saveAndFlush(claim);
534	        audit.recordOnCommit(record("CLAIM_REDATED", user, person, saved) + numberOf(saved.getNumber())
535	                + " old=" + old + " new=" + date);
536	        rollup.recordChanges(sheetId, user, before);
537	        return saved;
538	    }
