109	/** How many people the members are, those whose names or aliases match (as names are compared) being one. */
110	function distinctPeople(members: TreeMember[]): number {
111	  const parent = members.map((_, i) => i);
112	  const top = (i: number): number => (parent[i] === i ? i : top(parent[i]));
113	  const firstWith = new Map<string, number>();
114	  let count = members.length;
115	  members.forEach((m, i) => {
116	    for (const name of m.names) {
117	      const other = firstWith.get(name);
118	      if (other === undefined) {
119	        firstWith.set(name, i);
120	        continue;
121	      }
122	      const a = top(i);
123	      const b = top(other);
124	      if (a !== b) {
125	        parent[a] = b;
126	        count--;
127	      }
128	    }
129	  });
130	  return count;
131	}
