157	/**
158	 * Whether an open claim of the person, not bound by a statement, is left out of the live totals: any once their
159	 * retirement date is reached (the sheet's today on or after it).
160	 */
161	function leftOut(claim: Claim, person: LeftOutBy, today: string | null): boolean {
162	  const retired = person.retiredFrom !== null && today !== null && person.retiredFrom <= today;
163	  return !bound(claim) && retired;
164	}
