166	/**
167	 * Whether the claim counts in the live totals: an OPEN, PENDING or SETTLED one, but an OPEN or PENDING one
168	 * once their retirement date is reached, not unless a statement binds it, and one deferred
169	 * on the sheet's today not at all.
170	 */
171	function live(claim: Claim, person: LeftOutBy, today: string | null): boolean {
172	  return counts(claim, today) && !(isOpen(claim) && leftOut(claim, person, today));
173	}
174	
175	/** Whether the claim's amount counts in claimed: as {@link live}. */
176	function claimedLive(claim: Claim, person: LeftOutBy, today: string | null): boolean {
177	  return live(claim, person, today);
