180	/**
181	 * Whether the claim counts in a period's due-total: by the status it had at the end of the period's last day, an OPEN,
182	 * PENDING or SETTLED one, but one open then and still open now once
183	 * their retirement date is reached, not unless a statement binds it, and one deferred on the sheet's today not at all.
184	 */
185	function liveAtEnd(claim: Claim, person: LeftOutBy, today: string | null, end: string): boolean {
186	  const status = statusOn(claim, end);
187	  if (status === null || deferred(claim, today)) return false;
188	  const open = status === 'OPEN' || status === 'PENDING';
189	  return (open || status === 'SETTLED') && !(open && isOpen(claim) && leftOut(claim, person, today));
