156	            List<PersonGrade> grades = from.getGrades();
157	            Person arrived = new Person(to, from.getName(), grades.get(0).getGrade());
158	            grades.stream().skip(1).forEach(g -> arrived.setGrade(g.getGrade(), g.getFromDate()));
159	            arrived.setTerms(from.getTerms());
160	            from.getDatedTerms().forEach(t -> arrived.setTerms(t.getTerms(), t.getFromDate()));
