1898	  /**
1899	   * The sum of the person's dues as {@link dueTotalOf} has it, before the cap: each of their claims' less the parts
1900	   * its holders have, and the parts they hold of the claims shared with them (which make it a figure, not n/a).
1901	   */
1902	  private uncappedDueTotalOf(person: Person): string {
1903	    const counted = this.claimsOf(person.id).filter((c) => live(c, person, this.session.today()));
1904	    const dues = counted.map((c) => claimDue(c, this.rates(), person.grades, this.session));
1905	    const held = this.heldParts().get(person.id) ?? [];
1906	    const today = this.session.today();
1907	    // A due under a grade the person had on an earlier date counts too.
1908	    const anyDated = today !== null && counted.some((c, i) => dues[i] !== 'n/a' && c.date <= today);
1909	    if (this.rateOf(this.gradeOf(person)) === undefined && !counted.some(dueFixed) && !anyDated && held.length === 0) {
1910	      return 'n/a';
1911	    }
1912	    return sumDues([...counted.map((c, i) => this.ownPartOf(c, dues[i])), ...held.map((h) => h.part)]);
1913	  }
