1915	  /**
1916	   * The parts of the shared claims each person holds, by holder id: for each claim that counts in its own person's live
1917	   * totals and has a due, the holder's part as {@link partOf} has it; a holder whose grade has no rate holds none.
1918	   */
1919	  private readonly heldParts = computed(() => {
1920	    const today = this.session.today();
1921	    const by = new Map<number, { claim: Claim; part: string }[]>();
1922	    for (const owner of this.people()) {
1923	      for (const c of this.claimsOf(owner.id)) {
1924	        if ((c.shares ?? []).length === 0 || !live(c, owner, today)) continue;
1925	        const due = claimDue(c, this.rates(), owner.grades, this.session);
1926	        if (due === 'n/a') continue;
1927	        for (const h of c.shares) {
1928	          const part = this.partOf(c, h, due);
1929	          if (part === 'n/a') continue;
1930	          const list = by.get(h.personId) ?? [];
1931	          list.push({ claim: c, part });
1932	          by.set(h.personId, list);
1933	        }
1934	      }
1935	    }
1936	    return by;
1937	  });
