1939	  /**
1940	   * A holder's part of a shared claim with the due: a SETTLED claim's frozen part, its settled due times the share
1941	   * divided by 100 rounded half to even; else the claim's amount times the share divided by 100, times the rate of the
1942	   * holder's own grade in force on the claim's date divided by 100, rounded like the claim; n/a when their grade has no
1943	   * rate then (0.00 off the claim's own person).
1944	   */
1945	  private partOf(claim: Claim, holding: ClaimShare, due: string): string {
1946	    if (claim.settledDue !== null) return sumShared([{ figure: due, share: holding.share }]);
1947	    const holder = this.people().find((p) => p.id === holding.personId);
1948	    const grade = holder === undefined ? undefined : gradeOn(holder.grades, claim.date);
1949	    const pct = grade === undefined ? undefined : rateOn(this.rates(), grade, claim.date, claim.rateStamp);
1950	    return pct === undefined ? 'n/a' : sharedPartOf(claim.amount, holding.share, pct, roundingOf(claim, this.session));
1951	  }
