1954	  private ownPartOf(claim: Claim, due: string): string {
1955	    if (due === 'n/a' || (claim.shares ?? []).length === 0) return due;
1956	    return changeFrom(due, sumDues(claim.shares.map((h) => this.partOf(claim, h, due)).filter((p) => p !== 'n/a')));
1957	  }
