1981	  /** As {@link liveDuesOf}, each claim less its holders' parts, with the parts the person holds of claims passing the test. */
1982	  private liveSharedDuesOf(person: Person, test: (c: Claim) => boolean): string {
1983	    const today = this.session.today();
1984	    const own = this.claimsOf(person.id)
1985	      .filter((c) => test(c) && live(c, person, today))
1986	      .map((c) => this.ownPartOf(c, claimDue(c, this.rates(), person.grades, this.session)));
1987	    const held = (this.heldParts().get(person.id) ?? []).filter((h) => test(h.claim)).map((h) => h.part);
