2049	  /**
2050	   * The dues of the person's OPEN and PENDING claims that count in the live totals, split by the claim's age on the
2051	   * sheet's today (the days from its date): 0 to 30 (a claim dated after today too), 31 to 60, and 61 or more; each
2052	   * skipping the n/a ones.
2053	   */
2054	  protected agedOf(person: Person): [string, string, string] {
2055	    const today = this.session.today();
2056	    const buckets: [string[], string[], string[]] = [[], [], []];
2057	    if (today !== null) {
2058	      for (const c of this.claimsOf(person.id)) {
2059	        if (!isOpen(c) || !live(c, person, today)) continue;
2060	        const days = Math.round((Date.parse(today) - Date.parse(c.date)) / 86_400_000);
2061	        buckets[days <= 30 ? 0 : days <= 60 ? 1 : 2].push(claimDue(c, this.rates(), person.grades, this.session));
2062	      }
2063	    }
2064	    return [sumDues(buckets[0]), sumDues(buckets[1]), sumDues(buckets[2])];
2065	  }
