87	    /** Merge the person into the other; the other, as it now stands. */
88	    @Transactional
89	    public Person merge(String sheetId, String user, Long id, Long intoId) {
90	        Person from = people.findForUpdate(id, sheetId)
91	                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
92	        Person into = people.findForUpdate(intoId, sheetId)
93	                .orElseThrow(() -> new PersonNotFoundException(sheetId, intoId));
94	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
95	            throw new PersonMergeRefusedException("Only a steward can merge people");
96	        }
97	        if (from.getId().equals(into.getId())) {
98	            throw new PersonMergeRefusedException(from.getName() + " cannot be merged into themselves");
99	        }
100	        if (from.isRetired() || into.isRetired()) {
101	            throw new PersonMergeRefusedException("A retired person cannot be merged");
102	        }
103	        RollupService.Snapshot before = rollup.snapshot(sheetId);
104	        PersonMerge record = new PersonMerge(sheetId, from.getId(), into.getId(), user, sheets.today(sheetId));
105	
106	        // The claims, listed after the other's in the order they were added, each keeping any figure a statement bound.
107	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()).stream()
108	                .sorted(Comparator.comparingLong(Claim::getListed).thenComparing(Claim::getId))
109	                .toList();
110	        for (Claim claim : theirs) {
111	            record.getClaims().add(new PersonMerge.MovedClaim(claim.getId(), claim.getListed()));
112	            claim.setPersonId(into.getId());
113	            claim.setListed(sheets.nextListed(sheetId));
114	        }
115	        claims.saveAll(theirs);
116	
117	        // The shares they hold become the other's, added to any the other holds of the same claim; a share of a claim
118	        // that is now the other's own is dropped.
119	        List<Long> intoClaims = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, into.getId()).stream()
120	                .map(Claim::getId).toList();
121	        Map<Long, ClaimShare> intoHolds = new HashMap<>();
122	        for (ClaimShare share : shares.findByPersonIdOrderByIdAsc(into.getId())) {
123	            if (intoClaims.contains(share.getClaimId())) {
124	                shares.delete(share);
125	            } else {
126	                intoHolds.put(share.getClaimId(), share);
127	            }
128	        }
129	        for (ClaimShare share : shares.findByPersonIdOrderByIdAsc(from.getId())) {
130	            ClaimShare held = intoHolds.get(share.getClaimId());
131	            if (intoClaims.contains(share.getClaimId())) {
132	                shares.delete(share);
133	            } else if (held != null) {
134	                held.setShare(held.getShare().add(share.getShare()));
135	                shares.delete(share);
136	            } else {
137	                share.setPersonId(into.getId());
138	            }
139	        }
140	        shares.flush();
141	
142	        // The name and aliases become the other's aliases; the name is free once the person is removed.
143	        List<PersonAlias> theirAliases = aliases.findByPersonId(from.getId());
144	        theirAliases.forEach(a -> a.setPersonId(into.getId()));
145	        theirAliases.forEach(a -> record.getAliasIds().add(a.getId()));
146	        aliases.saveAll(theirAliases);
147	
148	        // Patrons: the merged person's are added to the other's, and those naming them name the other instead.
149	        List<PersonPatron> all = patrons.findBySheetIdOrderByIdAsc(sheetId);
150	        Set<Long> intoPatrons = new HashSet<>();
151	        Set<String> pairs = new HashSet<>();
152	        for (PersonPatron p : all) {
153	            if (p.getPersonId().equals(into.getId())) {
154	                intoPatrons.add(p.getPatronId());
155	            }
156	            if (!p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId())) {
157	                pairs.add(p.getPersonId() + ":" + p.getPatronId());
158	            }
159	        }
160	        List<PersonPatron> dropped = new ArrayList<>();
161	        List<PersonPatron> moved = new ArrayList<>();
162	        for (PersonPatron p : all) {
163	            if (!p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId())) {
164	                continue;
165	            }
166	            Long person = p.getPersonId().equals(from.getId()) ? into.getId() : p.getPersonId();
167	            Long patron = p.getPatronId().equals(from.getId()) ? into.getId() : p.getPatronId();
168	            if (person.equals(patron) || !pairs.add(person + ":" + patron)) {
169	                dropped.add(p);
170	            } else {
171	                p.setPersonId(person);
172	                p.setPatronId(patron);
173	                moved.add(p);
174	            }
175	        }
176	        patrons.deleteAll(dropped);
177	        patrons.flush();
178	        patrons.saveAll(moved);
179	
180	        // Pool memberships move, shares added where the other is a member already.
181	        for (Pool pool : pools.findBySheetIdOrderByIdAsc(sheetId)) {
182	            PoolMember membership = pool.getMembers().stream()
183	                    .filter(m -> from.getId().equals(m.getPersonId())).findFirst().orElse(null);
184	            if (membership == null) {
185	                continue;
186	            }
187	            PoolMember existing = pool.getMembers().stream()
188	                    .filter(m -> into.getId().equals(m.getPersonId())).findFirst().orElse(null);
189	            if (existing != null) {
190	                existing.setShare(existing.getShare().add(membership.getShare()));
191	                pool.getMembers().remove(membership);
192	            } else {
193	                membership.setPersonId(into.getId());
194	            }
195	            pools.saveAndFlush(pool);
196	        }
197	
198	        // Crews follow: a crew the person leads is led by the other, and a membership moves, dropped where the other
199	        // already leads or is in the crew.
200	        for (Crew crew : crews.findBySheetIdOrderByIdAsc(sheetId)) {
201	            boolean changed = false;
202	            if (from.getId().equals(crew.getLeadId())) {
203	                crew.setLeadId(into.getId());
204	                crew.getMembers().removeIf(m -> into.getId().equals(m.getPersonId()));
205	                changed = true;
206	            }
207	            var membership = crew.getMembers().stream()
208	                    .filter(m -> from.getId().equals(m.getPersonId())).findFirst().orElse(null);
209	            if (membership != null) {
210	                if (crew.includes(into.getId())) {
211	                    crew.getMembers().remove(membership);
212	                } else {
213	                    membership.setPersonId(into.getId());
214	                }
215	                changed = true;
216	            }
217	            if (changed) {
218	                crews.saveAndFlush(crew);
219	            }
220	        }
221	
222	        // A closed period's fixed figures follow the claims.
223	        for (Period period : periods.findBySheetIdOrderByFromDateAscIdAsc(sheetId)) {
224	            if (period.getPersonTotals().containsKey(from.getId())
225	                    || period.getPersonCarried().containsKey(from.getId())
226	                    || period.getPersonOpenings().containsKey(from.getId())) {
227	                period.mergePersonTotal(from.getId(), into.getId());
228	                periods.save(period);
229	            }
230	        }
231	
232	        // Statements are counted with the other's (whose last stays theirs, or with none becomes the merged one's);
233	        // watchers, plans, holds and contact go with the person, who is kept aside.
234	        statements.follow(from, into);
235	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
236	        claims.flush();
237	        plans.deleteByPersonId(from.getId());
238	        from.mergeAway();
239	        people.saveAndFlush(from);
240	        record.setNameAliasId(aliases.saveAndFlush(new PersonAlias(sheetId, into.getId(), from.getName())).getId());
241	        merges.save(record);
242	
243	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user
244	                + " from=" + from.getName() + " into=" + into.getName());
245	        rollup.recordChanges(sheetId, user, before);
246	        return into;
247	    }
