249	    /** Undo the last merge into the person; the person merged, back on the sheet. */
250	    @Transactional
251	    public Person undo(String sheetId, String user, Long intoId) {
252	        Person into = people.findForUpdate(intoId, sheetId)
253	                .orElseThrow(() -> new PersonNotFoundException(sheetId, intoId));
254	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
255	            throw new PersonMergeRefusedException("Only a steward can undo a merge");
256	        }
257	        PersonMerge merge = merges.findFirstBySheetIdAndIntoIdOrderByIdDesc(sheetId, into.getId())
258	                .orElseThrow(() -> new PersonMergeRefusedException("No one was merged into " + into.getName()));
259	        if (!merge.getMergedBy().equals(user)) {
260	            throw new PersonMergeRefusedException("Only " + merge.getMergedBy() + " can undo that merge");
261	        }
262	        if (!merge.getMergedOn().equals(sheets.today(sheetId))) {
263	            throw new PersonMergeRefusedException("A merge can only be undone on the day it was made");
264	        }
265	        String name = people.findMergedAwayName(merge.getFromId(), sheetId)
266	                .orElseThrow(() -> new PersonMergeRefusedException("The merged person is no longer kept"));
267	        String key = Person.key(name);
268	        if (people.existsBySheetIdAndNameKey(sheetId, key)) {
269	            throw new PersonMergeRefusedException("Someone on the sheet is named " + name + " now");
270	        }
271	        RollupService.Snapshot before = rollup.snapshot(sheetId);
272	
273	        // The claims that came from them and are still the other's go back, to their places before.
274	        for (PersonMerge.MovedClaim moved : merge.getClaims()) {
275	            claims.findById(moved.claimId())
276	                    .filter(c -> sheetId.equals(c.getSheetId()) && into.getId().equals(c.getPersonId()))
277	                    .ifPresent(c -> {
278	                        c.setPersonId(merge.getFromId());
279	                        c.setListed(moved.listed());
280	                        claims.save(c);
281	                    });
282	        }
283	        claims.flush();
284	
285	        // Their own aliases leave the other's, and the alias their name became is removed.
286	        if (merge.getNameAliasId() != null) {
287	            aliases.findById(merge.getNameAliasId()).ifPresent(aliases::delete);
288	        }
289	        for (PersonAlias alias : aliases.findAllById(merge.getAliasIds())) {
290	            if (into.getId().equals(alias.getPersonId())) {
291	                alias.setPersonId(merge.getFromId());
292	            }
293	        }
294	        aliases.flush();
295	        if (aliases.existsBySheetIdInAndAliasKeyAndPersonIdNot(List.of(sheetId), key, merge.getFromId())) {
296	            throw new PersonMergeRefusedException("Someone on the sheet goes by " + name + " now");
297	        }
298	
299	        merges.delete(merge);
300	        merges.flush();
301	        people.bringBack(merge.getFromId(), sheetId, key, people.maxPosition(sheetId) + 1);
302	        Person restored = people.findByIdAndSheetId(merge.getFromId(), sheetId)
303	                .orElseThrow(() -> new PersonNotFoundException(sheetId, merge.getFromId()));
304	
305	        audit.recordOnCommit("PERSON_MERGE_UNDONE sheet=" + sheetId + " by=" + user
306	                + " name=" + restored.getName() + " from=" + into.getName());
307	        rollup.recordChanges(sheetId, user, before);
308	        return restored;
309	    }
310	}
