3067	  private async read(sheet: string): Promise<void> {
3068	    const read = ++this.reads;
3069	    const load = this.session.loaded();
3070	    const url = `/api/sheets/${encodeURIComponent(sheet)}`;
3071	    const [list, claims, rates, periods, tags, descendants] = await Promise.all([
3072	      firstValueFrom(this.http.get<Person[]>(`${url}/people`, this.session.headers())),
3073	      firstValueFrom(this.http.get<Claim[]>(`${url}/claims`, this.session.headers())),
3074	      firstValueFrom(this.http.get<Rate[]>(`${url}/rates`, this.session.headers())),
3075	      firstValueFrom(this.http.get<Period[]>(`${url}/periods`, this.session.headers())),
3076	      firstValueFrom(this.http.get<string[]>(`${url}/claims/tags`, this.session.headers())),
3077	      firstValueFrom(this.http.get<DescendantFigures>(`${url}/descendants/figures`, this.session.headers())),
3078	    ]).catch(() => [null, null, null, null, null, null]);
3079	    // A later read wins over a slower earlier one.
3080	    if (list && claims && rates && periods && tags && descendants && read === this.reads && this.session.sheet() === sheet) {
3081	      this.people.set(list);
3082	      this.claims.set(claims);
3083	      this.rates.set(rates);
3084	      this.periods.set(periods);
3085	      this.tags.set(tags);
3086	      this.descendantFigures.set(descendants);
3087	      this.session.shown('people', load);
3088	    }
3089	  }
