118	    /** Clone the sheet to the other id; the clone as made. */
119	    @Transactional
120	    public Sheet cloneTo(String sheetId, String user, String toSheetId) {
121	        Sheet from = sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
122	        if (roleService.roleOf(sheetId, user) != Role.STEWARD) {
123	            throw new SheetCloneRefusedException("Only a steward can clone the sheet");
124	        }
125	        String to = toSheetId == null ? "" : toSheetId.trim();
126	        if (to.isEmpty()) {
127	            throw new SheetCloneRefusedException("Type the id of the sheet to clone to");
128	        }
129	        if (to.length() > 100) {
130	            throw new SheetCloneRefusedException("A sheet id is at most 100 characters");
131	        }
132	        if (sheets.existsById(to)) {
133	            throw new SheetCloneRefusedException("Sheet " + to + " is already in use");
134	        }
135	        Sheet clone = from.copyTo(to, user);
136	        try {
137	            entities.persist(clone);
138	            entities.flush();
139	        } catch (PersistenceException | DataIntegrityViolationException e) {
140	            // Someone started the same sheet at the same moment.
141	            throw new SheetCloneRefusedException("Sheet " + to + " is already in use");
142	        }
143	
144	        for (SheetRole role : roles.findBySheetIdOrderByUserNameAsc(sheetId)) {
145	            roles.save(new SheetRole(to, role.getUserName(), role.getRole()));
146	        }
147	        for (Rate rate : rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId)) {
148	            Rate copy = new Rate(to, rate.getGrade(), rate.getFromDate(), rate.getPct());
149	            copy.setToDate(rate.getToDate());
150	            copy.setVersion(rate.getVersion());
151	            copy.setForwardAfter(rate.getForwardAfter());
152	            Long copyId = rates.save(copy).getId();
153	            rateVersions.findByRateIdOrderByVersionAsc(rate.getId())
154	                    .forEach(v -> rateVersions.save(v.copyTo(copyId)));
155	        }
156	        rateLogs.findBySheetIdOrderByIdAsc(sheetId).forEach(l -> rateLogs.save(l.copyTo(to)));
157	        holidays.findBySheetIdOrderByDateAsc(sheetId).forEach(h -> holidays.save(new Holiday(to, h.getDate())));
158	        voidReasons.findBySheetIdOrderByIdAsc(sheetId)
159	                .forEach(r -> voidReasons.save(new VoidReason(to, r.getReason())));
160	        templates.findBySheetIdOrderByNameAsc(sheetId)
161	                .forEach(t -> templates.save(new ClaimTemplate(to, t.getName(), t.getAmount(), t.getNote())));
162	        tags.findBySheetIdOrderByTagAsc(sheetId).forEach(t -> tags.save(new SheetTag(to, t.getTag())));
163	        for (Period period : periods.findBySheetIdOrderByFromDateAscIdAsc(sheetId)) {
164	            periods.save(new Period(to, period.getName(), period.getFromDate(), period.getToDate(),
165	                    period.getCap()));
166	        }
167	
168	        // The people as listed, with their aliases and patrons.
169	        Map<Long, Long> personIds = new HashMap<>();
170	        List<Person> theirPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
171	        for (Person person : theirPeople) {
172	            personIds.put(person.getId(), people.save(person.copyTo(to)).getId());
173	        }
174	        people.flush();
175	        for (PersonAlias alias : aliases.findBySheetId(sheetId).stream()
176	                .sorted(Comparator.comparing(PersonAlias::getId)).toList()) {
177	            aliases.save(new PersonAlias(to, personIds.get(alias.getPersonId()), alias.getAlias(),
178	                    alias.getAliasSlot()));
179	        }
180	        for (PersonPatron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
181	            patrons.save(new PersonPatron(to, personIds.get(patron.getPersonId()),
182	                    personIds.get(patron.getPatronId())));
183	        }
184	
185	        // The pools, then their members: a member may be another pool.
186	        List<Pool> theirPools = pools.findBySheetIdOrderByIdAsc(sheetId);
187	        Map<Long, Pool> poolCopies = new HashMap<>();
188	        for (Pool pool : theirPools) {
189	            poolCopies.put(pool.getId(), pools.saveAndFlush(new Pool(to, pool.getName())));
190	        }
191	        for (Pool pool : theirPools) {
192	            Pool copy = poolCopies.get(pool.getId());
193	            for (PoolMember member : pool.getMembers()) {
194	                PoolMember copied = member.getMemberPoolId() != null
195	                        ? PoolMember.ofPool(poolCopies.get(member.getMemberPoolId()).getId(), member.getShare())
196	                        : new PoolMember(personIds.get(member.getPersonId()), member.getShare());
197	                copied.setDates(member.getFromDate(), member.getToDate());
198	                copy.getMembers().add(copied);
199	            }
200	            pools.saveAndFlush(copy);
201	        }
202	
203	        // The crews, with their leads and members.
204	        for (Crew crew : crews.findBySheetIdOrderByIdAsc(sheetId)) {
205	            Crew copy = new Crew(to, crew.getName(),
206	                    crew.getLeadId() == null ? null : personIds.get(crew.getLeadId()));
207	            for (CrewMember member : crew.getMembers()) {
208	                copy.getMembers().add(new CrewMember(personIds.get(member.getPersonId())));
209	            }
210	            crews.saveAndFlush(copy);
211	        }
212	
213	        // The claims, person by person as listed, each person's in the order they were added, listed as they were.
214	        Map<Long, List<ClaimLog>> logOf = new HashMap<>();
215	        logs.findBySheetIdOrderByIdAsc(sheetId)
216	                .forEach(l -> logOf.computeIfAbsent(l.getClaimId(), k -> new ArrayList<>()).add(l));
217	        Map<Long, List<Claim>> claimsOf = new HashMap<>();
218	        claims.findBySheetIdOrderByIdDesc(sheetId)
219	                .forEach(c -> claimsOf.computeIfAbsent(c.getPersonId(), k -> new ArrayList<>()).add(c));
220	        List<Claim> originals = new ArrayList<>();
221	        for (Person person : theirPeople) {
222	            originals.addAll(claimsOf.getOrDefault(person.getId(), List.of()).stream()
223	                    .sorted(Comparator.comparing(Claim::getId)).toList());
224	        }
225	        Map<Claim, Claim> copies = new HashMap<>();
226	        List<Claim> added = new ArrayList<>();
227	        for (Claim claim : originals) {
228	            Claim copy = claim.copyTo(to, personIds.get(claim.getPersonId()));
229	            copy.setListed(claim.getListed());
230	            Claim saved = claims.save(copy);
231	            copies.put(claim, saved);
232	            added.add(saved);
233	        }
234	        claims.flush();
235	        sheets.setLastListed(to, sheets.lastListed(sheetId));
236	
237	        // Numbered anew in the order the originals were opened, by the clone's own numbering.
238	        Map<String, String> numbers = new HashMap<>();
239	        Map<Claim, LocalDate> openedOn = new HashMap<>();
240	        originals.forEach(c -> openedOn.put(copies.get(c), openedOn(c, logOf.getOrDefault(c.getId(), List.of()))));
241	        for (Claim claim : originals.stream().filter(c -> c.getNumber() != null)
242	                .sorted(Comparator.comparing((Claim c) -> openedOn.get(copies.get(c)))
243	                        .thenComparing(c -> copies.get(c).getId()))
244	                .toList()) {
245	            Claim copy = copies.get(claim);
246	            copy.setNumber(claimService.nextNumber(to, copy.getDueBy()));
247	            numbers.put(claim.getNumber(), copy.getNumber());
248	        }
249	        for (Claim copy : added) {
250	            if (copy.getCorrects() != null) {
251	                copy.setCorrects(numbers.getOrDefault(copy.getCorrects(), copy.getCorrects()));
252	            }
253	            if (copy.getSplitFrom() != null) {
254	                copy.setSplitFrom(numbers.getOrDefault(copy.getSplitFrom(), copy.getSplitFrom()));
255	            }
256	        }
257	        claims.saveAllAndFlush(added);
258	        for (Claim claim : originals) {
259	            Long copyId = copies.get(claim).getId();
260	            for (ClaimLog log : logOf.getOrDefault(claim.getId(), List.of())) {
261	                logs.save(new ClaimLog(to, copyId, log.getStatus(), log.getBy(), log.getDate(), log.getDue()));
262	            }
263	        }
264	        logs.flush();
265	
266	        audit.recordOnCommit("SHEET_CLONE_MADE sheet=" + sheetId + " by=" + user + " to=" + to);
267	        audit.recordOnCommit("SHEET_CLONED sheet=" + to + " by=" + user + " from=" + sheetId);
268	        rollup.recordAll(to, user);
269	        return clone;
270	    }
271	
272	    /** The sheet's today when the claim was opened: its first log line past DRAFT, else its date. */
273	    private static LocalDate openedOn(Claim claim, List<ClaimLog> log) {
274	        return log.stream().filter(l -> l.getStatus() != ClaimStatus.DRAFT && l.getStatus() != ClaimStatus.DELETED)
275	                .map(ClaimLog::getDate).findFirst().orElse(claim.getDate());
276	    }
