1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { FigurePipe } from '../../core/locale';
3	import { Component, OnInit, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
4	import { firstValueFrom } from 'rxjs';
5	import { Session } from '../../core/session';
6	import { Templates } from '../../core/templates';
7	import { VoidReasons } from '../../core/void-reasons';
8	import { Period, periodOn } from '../periods/periods';
9	import { Rate, Rounding, dueOf, floored, percentOf, rateOn, sumDues } from '../rates/rates';
10	
11	export interface Claim {
12	  id: number;
13	  personId: number;
14	  /** Two decimals, e.g. "2.50". */
15	  amount: string;
16	  /** yyyy-mm-dd */
17	  date: string;
18	  note: string;
19	  status: ClaimStatus;
20	  /** Given when the claim is opened; null for a DRAFT and once voided. */
21	  number: string | null;
22	  /** The due fixed when the claim was settled, two decimals; null when it has none and its due is live. */
23	  settledDue: string | null;
24	  /** The user who opened the claim; null for a DRAFT. That user cannot settle it. */
25	  openedBy: string | null;
26	  /** Whether the person's last statement bound the claim: it then shows the due it bound it to. */
27	  stated: boolean;
28	  /** The due the last statement bound the claim to, two decimals; null when unbound, or bound with none (n/a). */
29	  statedDue: string | null;
30	  /** The number of the SETTLED claim of the same person this claim corrects; null unless it is a correction. */
31	  corrects: string | null;
32	  /** The date (yyyy-mm-dd) that decides how its live figures round: its own, or a correction's corrected claim's. */
33	  roundingDate: string;
34	  /** Its place in its person's list: a claim with a later place is listed first (newest added, or last reassigned). */
35	  listed: number;
36	  /** The day (yyyy-mm-dd) the claim is due by, fixed when it was added from its person's terms in force on the sheet's today then. */
37	  dueBy: string;
38	  /** Its status log, oldest first: one line per status it has had. */
39	  log: ClaimLogLine[];
40	  /** The date (yyyy-mm-dd) an OPEN claim is deferred until; null when it was never deferred. */
41	  deferredUntil: string | null;
42	  /** How many proofs the claim has: one above the proof threshold on its date cannot be settled or approved with none. */
43	  proofs: number;
44	  /** The number of the claim this one was split off; null unless it was split off another. */
45	  splitFrom: string | null;
46	  /** The user whose open editor locks the claim against other users' edits; null when not locked. */
47	  lockedBy: string | null;
48	  /** Whether the claim was added while the period its due-by falls in was soft-closed. */
49	  lateEntry: boolean;
50	  /** The last day (yyyy-mm-dd) a reminder was written for the claim; null when it was never reminded. */
51	  remindedOn: string | null;
52	  /** The claim's external reference, unique on the sheet regardless of case; null when it has none. */
53	  ref: string | null;
54	  /** The claim's tags: trimmed, lower-cased, without repeats, sorted and joined by commas; null when it has none. */
55	  tags: string | null;
56	  /** The reason the claim was voided with, from the sheet's list; null when none. */
57	  voidReason: string | null;
58	  /** Its comments, oldest first. */
59	  comments: ClaimComment[];
60	  /** The number of the bulk settle that settled it (or sent it to PENDING); null when settled one at a time, or not settled. */
61	  settleBatch: number | null;
62	  /** The stamp a forward-only rate is matched against: the claim sees one whose forwardAfter is below it. */
63	  rateStamp: number;
64	  /** The day (yyyy-mm-dd) the claim last went to REVIEW; null when it never did. */
65	  reviewOn: string | null;
66	  /** The day (yyyy-mm-dd) the claim last went to PENDING; null when it never did. */
67	  pendingOn: string | null;
68	  /** Its lines, oldest first: with any, its amount is their quantities times their unit amounts added up. */
69	  lines: ClaimLine[];
70	  /** Whether a steward waived its late charge: it then bears none, whatever its overdue state. */
71	  waived: boolean;
72	  /** How many proofs it has of each kind (receipt, photo), by kind. */
73	  proofsByKind: Record<string, number>;
74	  /** Whether the claim is held: an OPEN or PENDING one then leaves the live totals unless a statement binds it. */
75	  held: boolean;
76	  /** The people the claim is shared with, in the order they were added. */
77	  shares: ClaimShare[];
78	  /** The user a steward assigned its review to; null when no one. */
79	  reviewAssignee: string | null;
80	}
81	
82	/** A person a claim is shared with, and their share of its due: a percent with two decimals, e.g. "33.33". */
83	export interface ClaimShare {
84	  personId: number;
85	  share: string;
86	}
87	
88	/** The kinds a proof can be: one added with none chosen is a receipt. */
89	const PROOF_KINDS = ['receipt', 'photo'] as const;
90	
91	/** A line of a claim: a label, a quantity (a whole number, at least 1) and a unit amount (two decimals). */
92	export interface ClaimLine {
93	  label: string;
94	  qty: number;
95	  unit: string;
96	}
97	
98	/** What is typed for a new line of a claim. */
99	interface LineEntry {
100	  label: string;
101	  qty: string;
102	  unit: string;
103	}
104	
105	/** A comment on a claim: who wrote it, the sheet's today then, and its text. */
106	export interface ClaimComment {
107	  by: string;
108	  /** yyyy-mm-dd */
109	  date: string;
110	  text: string;
111	}
112	
113	/** A line of a claim's status log: the status, who changed it, the sheet's today then, and the due then (or n/a). */
114	export interface ClaimLogLine {
115	  status: ClaimStatus;
116	  by: string;
117	  /** yyyy-mm-dd */
118	  date: string;
119	  due: string;
120	}
121	
122	/** Claims as listed: the latest list place first. */
123	export function byListed(a: Claim, b: Claim): number {
124	  return b.listed - a.listed || b.id - a.id;
125	}
126	
127	/**
128	 * DRAFT when added, then OPEN, then SETTLED; a clerk settling above the clerk limit makes it PENDING until a steward
129	 * approves (SETTLED) or rejects it (OPEN). A DRAFT, OPEN or PENDING claim may be VOID, and a steward may void a
130	 * SETTLED one within 7 days of its settlement. A DRAFT claim may be DELETED, counting nowhere, and restored to DRAFT on
131	 * the sheet's today it was deleted. A DRAFT claim whose due is above the review threshold on its date goes to REVIEW when
132	 * opened, counting nowhere until a steward reviews it to OPEN; it may be VOID.
133	 */
134	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
135	
136	/** The claim's tags, sorted; none when it has none. */
137	export function tagsOf(claim: Claim): string[] {
138	  return claim.tags === null ? [] : claim.tags.split(',');
139	}
140	
141	/** Whether a claim is a correction (a negative amount): its due has no floor and no late charge. */
142	export function isCorrection(claim: Claim): boolean {
143	  return claim.amount.trim().startsWith('-') && /[1-9]/.test(claim.amount);
144	}
145	
146	/**
147	 * Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED ones do, but not one deferred on
148	 * the sheet's today.
149	 */
150	export function counts(claim: Claim, today: string | null): boolean {
151	  return (isOpen(claim) || claim.status === 'SETTLED') && !deferred(claim, today);
152	}
153	
154	/**
155	 * Whether the claim is deferred on the sheet's today: an OPEN claim deferred until a later date, and not bound by a
156	 * statement. It then counts in no total, is not overdue, cannot be settled and is left unbound by a statement. While a
157	 * statement binds it the deferral waits; once the binding ends it takes effect, on a claim settled meanwhile too.
158	 */
159	export function deferred(claim: Claim, today: string | null): boolean {
160	  return (claim.status === 'OPEN' || claim.status === 'SETTLED') && !bound(claim)
161	    && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
162	}
163	
164	/**
165	 * The status the claim had at the end of the date, as its status log records it: its last line logged on or before
166	 * the date; null when it has lines but none by then (it was added later). With no log at all, its status now.
167	 */
168	export function statusOn(claim: Claim, date: string): ClaimStatus | null {
169	  if (claim.log.length === 0) return claim.status;
170	  let found: ClaimStatus | null = null;
171	  for (const line of claim.log) if (line.date <= date) found = line.status;
172	  return found;
173	}
174	
175	/** Whether a claim is handled as open: OPEN or PENDING. It goes overdue, bears the late charge, and a hold takes it out. */
176	export function isOpen(claim: Claim): boolean {
177	  return claim.status === 'OPEN' || claim.status === 'PENDING';
178	}
179	
180	/** Whether the claim's due follows its last statement now: any claim it bound, a PENDING one included. */
181	export function bound(claim: Claim): boolean {
182	  return claim.stated;
183	}
184	
185	/** One of a person's grades, from its from-date (yyyy-mm-dd); null from the beginning of time. */
186	export interface PersonGrade {
187	  grade: string;
188	  from: string | null;
189	}
190	
191	/** The person's grade in force on the date: the one with the latest from-date on or before it. */
192	export function gradeOn(grades: PersonGrade[], date: string): string | undefined {
193	  let found: PersonGrade | undefined;
194	  for (const g of grades) {
195	    if (g.from !== null && g.from > date) continue;
196	    if (found === undefined || (found.from ?? '') <= (g.from ?? '')) found = g;
197	  }
198	  return found?.grade;
199	}
200	
201	/**
202	 * How the claim's live figures round: by the rounding mode in force on its date when there is one, else half up when
203	 * its rounding date is before the sheet's policy date (the sheet's today when blank), half to even on or after it.
204	 */
205	export function roundingOf(claim: Claim, session: Session): Rounding {
206	  const mode = session.settingOn('rounding', claim.date);
207	  if (mode === 'half-up' || mode === 'half-even') return mode;
208	  const policy = session.policyDate() || session.today();
209	  return policy !== null && claim.roundingDate < policy ? 'half-up' : 'half-even';
210	}
211	
212	/**
213	 * The due fixed when the claim was settled, else the due its person's last statement bound it to (as shown then, late
214	 * charge included), else the greater of the floor in force on its date and its figure (its amount times the rate of its
215	 * person's grade on its date, both in force on its date, or n/a with no rate), with the late charge on that added on top. A
216	 * correction has neither floor nor late charge.
217	 */
218	export function claimDue(claim: Claim, rates: Rate[], grades: PersonGrade[], session: Session): string {
219	  if (claim.settledDue !== null) return claim.settledDue;
220	  if (bound(claim)) return claim.statedDue ?? 'n/a';
221	  const grade = gradeOn(grades, claim.date);
222	  const figure = dueOf(claim.amount, grade === undefined ? undefined : rateOn(rates, grade, claim.date, claim.rateStamp), roundingOf(claim, session));
223	  if (figure === 'n/a' || isCorrection(claim)) return figure;
224	  const base = floored(figure, session.settingOn('floor', claim.date));
225	  return sumDues([base, lateCharge(claim, base, grades, session)]);
226	}
227	
228	/**
229	 * The day the claim goes overdue after, and its late charge counts from: its due-by plus the grace days of its person's
230	 * grade on its date in force on that date, else its due-by. The due-by shown stays as it is.
231	 */
232	export function overdueBy(claim: Claim, grades: PersonGrade[], session: Session): string {
233	  if (claim.dueBy === '') return claim.dueBy;
234	  const grade = gradeOn(grades, claim.date);
235	  const grace = grade === undefined ? null : session.settingOn('grace-' + grade, claim.date);
236	  return grace === null || grace === '' ? claim.dueBy : plusDays(claim.dueBy, Number(grace));
237	}
238	
239	/**
240	 * For every full 30 days an OPEN claim is past its due-by (plus its grace) on the sheet's today, the late percent in
241	 * force on that boundary (the due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the charges of the
242	 * boundaries before it (compounding), each rounded like the claim's due, added up; 0.00 when it is not overdue, and on a correction.
243	 */
244	export function lateCharge(claim: Claim, figure: string, grades: PersonGrade[], session: Session): string {
245	  const by = overdueBy(claim, grades, session);
246	  const today = session.today();
247	  if (!isOpen(claim) || isCorrection(claim) || by === '' || today === null) return '0.00';
248	  if (deferred(claim, today) || claim.waived) return '0.00';
249	  const days = Math.round((Date.parse(today) - Date.parse(by)) / 86_400_000);
250	  const charges: string[] = [];
251	  for (let boundary = 1; boundary <= Math.floor(days / 30); boundary++) {
252	    const pct = session.settingOn('late-pct', plusDays(by, 30 * boundary));
253	    if (pct !== null) charges.push(percentOf(sumDues([figure, ...charges]), pct, 1, roundingOf(claim, session)));
254	  }
255	  return sumDues(charges);
256	}
257	
258	/** The yyyy-mm-dd date the days after the date. */
259	export function plusDays(date: string, days: number): string {
260	  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
261	}
262	
263	/** Whether the claim's due is fixed, by settling or by a statement, rather than worked out from the rates. */
264	export function dueFixed(claim: Claim): boolean {
265	  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
266	}
267	
268	/** Whether the claim is OPEN or PENDING, not deferred, and its due-by plus its grace is before the sheet's today. */
269	export function overdue(claim: Claim, grades: PersonGrade[], session: Session): boolean {
270	  const today = session.today();
271	  return isOpen(claim) && today !== null && overdueBy(claim, grades, session) < today && !deferred(claim, today);
272	}
273	
274	type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle' | 'delete' | 'restore' | 'review';
275	
276	/** Sums amounts with two decimals exactly, in whole cents. */
277	export function sumAmounts(amounts: string[]): string {
278	  const cents = amounts.reduce((total, a) => total + Math.round(Number(a) * 100), 0);
279	  return (cents / 100).toFixed(2);
280	}
