369	   168	    private static long[] cuts(long pot, List<Member> members, boolean[] excluded) {
370	   169	        int n = members.size();
371	   170	        long shares = 0;
372	   171	        for (int i = 0; i < n; i++) {
373	   172	            shares += excluded[i] ? 0 : members.get(i).share();
374	   173	        }
375	   174	        long[] out = new long[n];
376	   175	        if (shares == 0) {
377	   176	            return out;
378	   177	        }
379	   178	        for (int i = 0; i < n; i++) {
380	   179	            out[i] = excluded[i] ? 0 : cutOf(pot, members.get(i).share(), shares);
381	   180	        }
382	   181	        int smallest = -1;
383	   182	        for (int i = 0; i < n; i++) {
384	   183	            if (out[i] != 0 && (smallest < 0 || out[i] <= out[smallest])) {
385	   184	                smallest = i;
386	   185	            }
387	   186	        }
388	   187	        if (smallest < 0) {
389	   188	            for (int i = 0; i < n; i++) {
390	   189	                if (!excluded[i] && members.get(i).share() > 0) {
391	   190	                    smallest = i;
392	   191	                }
393	   192	            }
394	   193	        }
395	   194	        if (smallest >= 0) {
396	   195	            long sum = 0;
397	   196	            for (long c : out) {
398	   197	                sum += c;
399	   198	            }
400	   199	            out[smallest] += pot - sum;
401	   200	        }
402	   201	        return out;
403	   202	    }
