405	   204	    /** The pot times the share divided by the shares, rounded half to even. */
406	   205	    private static long cutOf(long pot, long share, long shares) {
407	   206	        long product = pot * share;
408	   207	        long whole = product / shares;
409	   208	        long rest = (product % shares) * 2;
410	   209	        boolean up = rest > shares || (rest == shares && whole % 2 == 1);
411	   210	        return up ? whole + 1 : whole;
412	   211	    }
